SELECT '01-10-2569/part_2009.json', '2026-10-01 00:47:27', 'part', 'parts_specifications', CONVERT( USING utf8mb4), NULL
WHERE NOT EXISTS (SELECT 1 FROM trash WHERE trash_id = '01-10-2569/part_2009.json');

